def main(algorithm:str)->None:
    p=argparse.ArgumentParser(description=__doc__);p.add_argument("--output-dir",required=True);p.add_argument("--steps",type=int,default=10000);p.add_argument("--max-steps",type=int);p.add_argument("--waypoint-radius",type=float,default=30.);p.add_argument("--batch-size",type=int,default=256);p.add_argument("--replay-capacity",type=int,default=100000);p.add_argument("--random-action-steps",type=int,default=2000);p.add_argument("--update-after-steps",type=int,default=2000);p.add_argument("--updates-per-step",type=int,default=1);p.add_argument("--exploration-noise-std",type=float,default=.1);p.add_argument("--log-interval",type=int,default=1000);p.add_argument("--evaluation-interval",type=int,default=5000);p.add_argument("--evaluation-episodes",type=int,default=10);p.add_argument("--checkpoint-interval",type=int);p.add_argument("--seed",type=int,default=0);p.add_argument("--evaluation-seed",type=int,default=10000);p.add_argument("--device",default="cpu");p.add_argument("--reward-rate",type=float,default=1.);p.add_argument("--reward-link",type=float,default=1.);p.add_argument("--reward-separation",type=float,default=1.);p.add_argument("--reward-intervention",type=float,default=1.);p.add_argument("--reward-motion",type=float,default=1.);p.add_argument("--reward-failure",type=float,default=1.);args=p.parse_args();np.random.seed(args.seed);torch.manual_seed(args.seed)
    weights=RewardWeights(args.reward_rate,args.reward_link,args.reward_separation,args.reward_intervention,args.reward_motion,args.reward_failure);config=scenario_environment_config(MultiRelayEnvironment().config,num_relays=4,waypoint_radius_m=args.waypoint_radius,max_steps=args.max_steps,reward_weights=weights);train_env=MultiRelayEnvironment(config);eval_env=MultiRelayEnvironment(config);obs,_=train_env.reset(seed=args.seed);cls=ParameterSharingMATD3 if algorithm=="matd3" else ParameterSharingMADDPG;agent=cls(obs["local"].shape[-1],obs["global"].shape[-1],config.num_relays,device=args.device);buffer=MultiAgentReplayBuffer(args.replay_capacity,config.num_relays,obs["local"].shape[-1],obs["global"].shape[-1],agent.action_dim);result=run_deterministic_experiment(train_env,eval_env,agent,buffer,DeterministicTrainingConfig(args.steps,args.replay_capacity,args.batch_size,args.random_action_steps,args.update_after_steps,args.updates_per_step,args.exploration_noise_std,args.seed),DeterministicExperimentConfig(args.output_dir,args.log_interval,args.evaluation_interval,args.evaluation_episodes,args.evaluation_seed,args.checkpoint_interval));print(json.dumps({"algorithm":algorithm,"output_directory":str(result.output_directory),"best_mean_return":result.best_mean_return},allow_nan=False))
